"""Demo 2 -- End-to-end audit of the hybrid seed compressor.

Builds the hybrid decompressor H_G (flag bit 0 = seed mode, flag bit 1 = literal
mode), computes the exact description complexity of all 2^n files by
shortest-first program enumeration, and verifies all four theorems about it:

  (a) every generator output has K <= s+1        -- the genuine win;
  (b) every file has K <= n+1                    -- the scheme never inflates;
  (c) some file has K >= n, and it is provably not a generator output
                                                 -- no free lunch;
  (d) at most a 2^(s+2-n) fraction has K <= s+1  -- the win is rare.

It prints the full complexity histogram, so one can see the thin spike of cheap
files (the generator's own outputs) beside the exponential wall of everything
else.
"""

from typing import Callable, Dict, Iterator, List, Sequence, Tuple

Bits = Tuple[int, ...]

N: int = 12
S: int = 4


def make_generator(n: int) -> Callable[[int], Bits]:
    def gen(seed: int) -> Bits:
        state = (seed + 1) * 2654435761 % (1 << 32)
        out: List[int] = []
        while len(out) < n:
            state = (1103515245 * state + 12345) % (1 << 32)
            for shift in range(16, 32):
                if len(out) == n:
                    break
                out.append((state >> shift) & 1)
        return tuple(out)
    return gen


def programs_upto(k: int) -> Iterator[Bits]:
    for length in range(k + 1):
        for v in range(1 << length):
            yield tuple((v >> i) & 1 for i in range(length))


def hybrid(p: Bits, gen: Callable[[int], Bits], n: int, s: int) -> Bits:
    if len(p) == 0:
        return tuple([0] * n)
    body: List[int] = list(p[1:])
    if p[0] == 0:
        body = (body + [0] * s)[:s]
        return gen(sum(b << i for i, b in enumerate(body)))
    body = (body + [0] * n)[:n]
    return tuple(body)


def main() -> None:
    gen = make_generator(N)
    profile: Dict[Bits, int] = {}
    for p in programs_upto(N + 1):
        x = hybrid(p, gen, N, S)
        if x not in profile:
            profile[x] = len(p)

    total = 1 << N
    outputs = {gen(seed) for seed in range(1 << S)}
    hardest, kmax = max(profile.items(), key=lambda kv: kv[1])
    cheap = [x for x, k in profile.items() if k <= S + 1]

    print(f"n = {N}, s = {S}, files = {total}")
    print(f"decompressor complete (every file has a program) : "
          f"{len(profile) == total}")
    print(f"(a) max K over generator outputs                 : "
          f"{max(profile[x] for x in outputs)}  (bound s+1 = {S+1})")
    print(f"(b) max K over all files                         : {kmax}"
          f"  (bound n+1 = {N+1})")
    print(f"(c) hardest file has K = {kmax} >= n = {N}            : {kmax >= N}")
    print(f"    is the hardest file a generator output?      : "
          f"{hardest in outputs}")
    print(f"(d) files with K <= s+1                          : {len(cheap)}"
          f" / {total} = {len(cheap)/total:.6f}")
    print(f"    ceiling 2^(s+2-n)                            : "
          f"{2.0**(S+2-N):.6f}")

    hist: Dict[int, int] = {}
    for k in profile.values():
        hist[k] = hist.get(k, 0) + 1
    print("\ncomplexity histogram")
    for k in sorted(hist):
        print(f"  K = {k:>3} : {hist[k]:>6}  {'#' * min(48, hist[k])}")

    mean = sum(profile.values()) / total
    print(f"\nmean description length : {mean:.4f} bits")
    print(f"literal-only baseline   : {N+1} bits")
    print("The flag bit taxes every file one bit in order to rebate n-s-1 bits")
    print("on a vanishing fraction of them: on uniform data, a net loss.")


if __name__ == "__main__":
    main()

