"""Algorithm 2 -- The Hybrid Seed/Literal Lossless Codec.

The best possible realization of "compress to the seed".  A single flag bit
selects between seed mode (s+1 bits, available only for generator outputs) and
literal mode (n+1 bits, always available).  The codec is exactly lossless on
every input and never expands by more than one bit.
"""

from typing import Callable, List, Optional, Sequence, Tuple

Bits = Tuple[int, ...]


def make_generator(n: int, mult: int = 1103515245,
                   inc: int = 12345) -> Callable[[int], Bits]:
    def gen(seed: int) -> Bits:
        state = (seed + 1) * 2654435761 % (1 << 32)
        out: List[int] = []
        while len(out) < n:
            state = (mult * state + inc) % (1 << 32)
            for shift in range(16, 32):
                if len(out) == n:
                    break
                out.append((state >> shift) & 1)
        return tuple(out)
    return gen


def int_to_bits(v: int, k: int) -> Bits:
    return tuple((v >> i) & 1 for i in range(k))


def bits_to_int(p: Sequence[int]) -> int:
    return sum(b << i for i, b in enumerate(p))


def pad(p: Sequence[int], k: int) -> Bits:
    q = list(p[:k])
    q.extend([0] * (k - len(q)))
    return tuple(q)


def hybrid_encode(x: Bits, generator: Callable[[int], Bits],
                  n: int, s: int) -> Bits:
    """Emit 0 || seed (length s+1) if x is a generator output, else 1 || x."""
    for seed in range(1 << s):
        if generator(seed) == x:
            return (0,) + int_to_bits(seed, s)
    return (1,) + tuple(x)


def hybrid_decode(p: Sequence[int], generator: Callable[[int], Bits],
                  n: int, s: int) -> Bits:
    """Inverse of hybrid_encode; total, so every program decodes to something."""
    if len(p) == 0:
        return tuple([0] * n)
    if p[0] == 0:
        return generator(bits_to_int(pad(p[1:], s)))
    return pad(p[1:], n)


def audit(n: int, s: int) -> None:
    """Verify losslessness on all 2^n inputs and report the length profile."""
    gen = make_generator(n)
    lengths: List[int] = []
    for v in range(1 << n):
        x = tuple((v >> i) & 1 for i in range(n))
        code = hybrid_encode(x, gen, n, s)
        assert hybrid_decode(code, gen, n, s) == x, "codec must be lossless"
        lengths.append(len(code))
    wins = sum(1 for L in lengths if L == s + 1)
    print(f"n = {n}, s = {s}")
    print(f"lossless on all {1 << n} inputs        : True")
    print(f"files coded in s+1 = {s+1} bits          : {wins}")
    print(f"files coded in n+1 = {n+1} bits          : {len(lengths)-wins}")
    print(f"fraction helped                        : {wins/len(lengths):.6f}"
          f"   (ceiling 2^(s+2-n) = {2.0**(s+2-n):.6f})")
    print(f"mean code length                       : "
          f"{sum(lengths)/len(lengths):.4f} bits  (literal-only: {n+1})")


if __name__ == "__main__":
    audit(n=12, s=4)

"""Algorithm 3 -- Exact Description-Complexity Profiling by Shortest-First
Program Enumeration, with automatic verification of the counting ceiling.

For a decompressor D on n-bit files, K_D(x) is the length of the shortest
program producing x.  Enumerating programs in shortest-first order and recording
the first program that reaches each file computes the entire profile in
Theta(2^(L+1)) decoder calls, where L is the maximum program length that need be
considered (L = n+1 for the hybrid codec, since literal mode always succeeds).

The routine then checks, for every d, the theoretical ceiling
    #{x : K_D(x) <= n-d} / 2^n  <=  2^(1-d),
which holds for every decompressor whatsoever.
"""

from typing import Callable, Dict, Iterator, List, Sequence, Tuple

Bits = Tuple[int, ...]


def programs_shortest_first(max_len: int) -> Iterator[Bits]:
    for length in range(max_len + 1):
        for v in range(1 << length):
            yield tuple((v >> i) & 1 for i in range(length))


def complexity_profile(decoder: Callable[[Bits], Bits], n: int,
                       max_len: int) -> Dict[Bits, int]:
    """Exact K_D for every file reachable by a program of length <= max_len."""
    best: Dict[Bits, int] = {}
    for p in programs_shortest_first(max_len):
        x = decoder(p)
        if x not in best:
            best[x] = len(p)
    return best


def verify_counting_ceiling(profile: Dict[Bits, int], n: int) -> bool:
    """Check #{x : K(x)+d <= n} <= 2^(n+1-d) for every d.  Returns True if all pass."""
    total = 1 << n
    ok = True
    print(f"{'d':>4} {'observed fraction':>20} {'ceiling 2^(1-d)':>18}  verdict")
    for d in range(0, n + 1):
        count = sum(1 for k in profile.values() if k + d <= n)
        observed = count / total
        ceiling = 2.0 ** (1 - d)
        good = observed <= ceiling + 1e-12
        ok = ok and good
        print(f"{d:>4} {observed:>20.10f} {ceiling:>18.10f}  "
              f"{'ok' if good else 'VIOLATED'}")
    return ok


def average_length_bound(n: int) -> Tuple[int, float]:
    """Best k and the resulting lower bound (n-k)(1-2^-k) on the mean length."""
    best_k = max(range(0, n), key=lambda k: (n - k) * (1 - 2.0 ** (-k)))
    return best_k, (n - best_k) * (1 - 2.0 ** (-best_k))


if __name__ == "__main__":
    # profile the hybrid seed/literal codec
    from typing import Optional

    n, s = 12, 4

    def make_generator(n: int) -> Callable[[int], Bits]:
        def gen(seed: int) -> Bits:
            state = (seed + 1) * 2654435761 % (1 << 32)
            out: List[int] = []
            while len(out) < n:
                state = (1103515245 * state + 12345) % (1 << 32)
                for shift in range(16, 32):
                    if len(out) == n:
                        break
                    out.append((state >> shift) & 1)
            return tuple(out)
        return gen

    gen = make_generator(n)

    def decoder(p: Bits) -> Bits:
        if len(p) == 0:
            return tuple([0] * n)
        body = list(p[1:])
        if p[0] == 0:
            body = (body + [0] * s)[:s]
            return gen(sum(b << i for i, b in enumerate(body)))
        body = (body + [0] * n)[:n]
        return tuple(body)

    profile = complexity_profile(decoder, n, n + 1)
    assert len(profile) == (1 << n), "decoder must be complete"
    print(f"profiled all {1 << n} files of length n = {n}\n")
    print("all ceilings respected:", verify_counting_ceiling(profile, n))
    k, bound = average_length_bound(n)
    mean = sum(profile.values()) / (1 << n)
    print(f"\nmean description length = {mean:.4f} bits")
    print(f"guaranteed lower bound at k = {k}: {bound:.4f} bits")

"""Algorithm 4 -- Index-Prefix Universal Decoder for a Finite Library,
and the search for a file that is hard for every member at once.

Given 2^m decompressors D_0, ..., D_{2^m - 1} on n-bit files, the universal
decoder U reads m index bits and runs the selected member on the remainder:

    U(indexbits(i) || p) = D_i(p).

Because the index field has fixed length m, the split is unambiguous, and the
invariance principle gives  K_U(x) <= m + K_{D_i}(x)  for every member i.
Applying the incompressibility theorem to U therefore produces a single file x
with  n <= m + K_{D_i}(x)  simultaneously for all i:  keeping a library of
generators buys exactly the m bits needed to name the one you used.
"""

from typing import Callable, Dict, Iterator, List, Sequence, Tuple

Bits = Tuple[int, ...]
Decoder = Callable[[Bits], Bits]


def int_to_bits(v: int, k: int) -> Bits:
    return tuple((v >> i) & 1 for i in range(k))


def bits_to_int(p: Sequence[int]) -> int:
    return sum(b << i for i, b in enumerate(p))


def universal_decoder(family: List[Decoder], m: int, n: int) -> Decoder:
    """Build U from the family; U is complete as soon as one member is."""

    def U(p: Bits) -> Bits:
        if len(p) < m:
            return family[0](())
        i = bits_to_int(p[:m])
        return family[i](tuple(p[m:]))

    return U


def programs_shortest_first(max_len: int) -> Iterator[Bits]:
    for length in range(max_len + 1):
        for v in range(1 << length):
            yield tuple((v >> i) & 1 for i in range(length))


def complexity_profile(decoder: Decoder, max_len: int) -> Dict[Bits, int]:
    best: Dict[Bits, int] = {}
    for p in programs_shortest_first(max_len):
        x = decoder(p)
        if x not in best:
            best[x] = len(p)
    return best


def hardest_for_family(family: List[Decoder], m: int, n: int,
                       max_len: int) -> Tuple[Bits, int, List[int]]:
    """Return a file maximizing K_U, together with its complexity under each
    member.  The invariance bound guarantees n <= m + K_{D_i}(x) for all i."""
    U = universal_decoder(family, m, n)
    prof_U = complexity_profile(U, max_len)
    x, kU = max(prof_U.items(), key=lambda kv: kv[1])
    per_member: List[int] = []
    for D in family:
        prof = complexity_profile(D, max_len)
        per_member.append(prof.get(x, max_len + 1))
    return x, kU, per_member


if __name__ == "__main__":
    n, s, m = 8, 3, 2

    def make_member(idx: int) -> Decoder:
        mult = 1103515245 + 2 * idx
        inc = 12345 + 7 * idx

        def gen(seed: int) -> Bits:
            state = (seed + 1) * 2654435761 % (1 << 32)
            out: List[int] = []
            while len(out) < n:
                state = (mult * state + inc) % (1 << 32)
                for shift in range(16, 32):
                    if len(out) == n:
                        break
                    out.append((state >> shift) & 1)
            return tuple(out)

        def D(p: Bits) -> Bits:
            if len(p) == 0:
                return tuple([0] * n)
            body = list(p[1:])
            if p[0] == 0:
                body = (body + [0] * s)[:s]
                return gen(bits_to_int(body))
            body = (body + [0] * n)[:n]
            return tuple(body)

        return D

    family: List[Decoder] = [make_member(i) for i in range(1 << m)]
    x, kU, per_member = hardest_for_family(family, m, n, n + 1 + m)
    print(f"library of 2^{m} = {1 << m} decompressors, n = {n}, s = {s}")
    print("hardest file       :", "".join(map(str, x)))
    print("K under universal U:", kU, f" (>= n = {n}: {kU >= n})")
    for i, k in enumerate(per_member):
        print(f"  member {i}: K = {k:>3}    m + K = {m + k:>3}  >= n ? "
              f"{m + k >= n}")
    print("\nOne file, simultaneously hard for the entire library.")

