"""Visualization: the description-complexity histogram against the counting ceiling.

Enumerates every program of length <= n+1 for the hybrid seed/literal decompressor
H_G and records, for each of the 2^n files, the length of the first (hence shortest)
program that produces it.  The resulting histogram of K_{H_G} is plotted against the
absolute ceiling #{x : K(x) = k} <= 2^k, which no decompressor can exceed.

The picture makes the whole theorem visible at a glance: a thin spike of cheap files
around k = s+1 (the generator's own outputs), and an exponential wall at k = n+1
where every other file sits.
"""

from typing import Callable, Dict, Iterator, List, Sequence, Tuple

import matplotlib.pyplot as plt

Bits = Tuple[int, ...]

N: int = 12          # file length in bits
S: int = 4           # seed length in bits


def all_programs_upto(k: int) -> Iterator[Bits]:
    for length in range(k + 1):
        for v in range(1 << length):
            yield tuple((v >> i) & 1 for i in range(length))


def bits_to_int(p: Sequence[int]) -> int:
    return sum(b << i for i, b in enumerate(p))


def pad(p: Sequence[int], n: int) -> Bits:
    q = list(p[:n])
    q.extend([0] * (n - len(q)))
    return tuple(q)


def make_generator(n: int) -> Callable[[int], Bits]:
    def gen(seed: int) -> Bits:
        state = (seed + 1) * 2654435761 % (1 << 32)
        out: List[int] = []
        while len(out) < n:
            state = (1103515245 * state + 12345) % (1 << 32)
            for shift in range(16, 32):
                if len(out) == n:
                    break
                out.append((state >> shift) & 1)
        return tuple(out)
    return gen


def hybrid_decode(p: Sequence[int], gen: Callable[[int], Bits],
                  n: int, s: int) -> Bits:
    if len(p) == 0:
        return tuple([0] * n)
    if p[0] == 0:
        return gen(bits_to_int(pad(p[1:], s)))
    return pad(p[1:], n)


def complexity_profile(n: int, s: int) -> Dict[Bits, int]:
    gen = make_generator(n)
    best: Dict[Bits, int] = {}
    for p in all_programs_upto(n + 1):
        x = hybrid_decode(p, gen, n, s)
        if x not in best:
            best[x] = len(p)
    return best


def main() -> None:
    profile = complexity_profile(N, S)
    hist: Dict[int, int] = {}
    for k in profile.values():
        hist[k] = hist.get(k, 0) + 1
    ks: List[int] = sorted(hist)
    counts: List[int] = [hist[k] for k in ks]
    ceiling: List[int] = [2 ** k for k in ks]

    fig, ax = plt.subplots(figsize=(9, 5.2))
    ax.bar(ks, counts, width=0.72, color="#3fb950",
           label=r"files with $K_{H_G}(x)=k$")
    ax.plot(ks, ceiling, "o--", color="#f0883e", linewidth=1.8,
            label=r"absolute ceiling $2^{k}$")
    ax.axvline(S + 1, color="#58a6ff", linestyle=":", linewidth=1.6)
    ax.text(S + 1.15, max(counts) * 0.45,
            f"seed mode\n$s+1={S+1}$ bits", color="#58a6ff", fontsize=9)
    ax.axvline(N, color="#f85149", linestyle=":", linewidth=1.6)
    ax.text(N - 3.4, max(counts) * 0.75,
            f"incompressible\nwitness at $n={N}$", color="#f85149", fontsize=9)
    ax.set_yscale("log")
    ax.set_xlabel("description length $k$ (bits)")
    ax.set_ylabel("number of files (log scale)")
    ax.set_title("A generator-powered compressor: a thin spike of wins, "
                 "an exponential wall of losses")
    ax.legend(frameon=False)
    ax.grid(alpha=0.25, linestyle=":")
    fig.tight_layout()
    fig.savefig("complexity_histogram.png", dpi=160)
    print("wrote complexity_histogram.png")


if __name__ == "__main__":
    main()
